import{_ as e,o as a,c as d,a2 as o}from"./chunks/framework.DoCD98hS.js";const h=JSON.parse('{"title":"qiankun 2 · 页签核心与主微应用模板","description":"","frontmatter":{},"headers":[],"relativePath":"modules/catalog/qiankun.md","filePath":"modules/catalog/qiankun.md","lastUpdated":1795055048000}'),r={name:"modules/catalog/qiankun.md"};function c(n,t,l,i,u,p){return a(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="qiankun-2-·-页签核心与主微应用模板" tabindex="-1">qiankun 2 · 页签核心与主微应用模板 <a class="header-anchor" href="#qiankun-2-·-页签核心与主微应用模板" aria-label="Permalink to &quot;qiankun 2 · 页签核心与主微应用模板&quot;">​</a></h1><p>页签核心由 Vue 2、Vue 3 和 React 适配包共用。两套 Vue 模板包含主应用和两个子应用，Vue 3 主应用还可挂载 React 子应用。</p><div class="info custom-block"><p class="custom-block-title">文档骨架</p><p>先占位目录与已核对的代表性能力，不是完整 API 清单。参数、完整示例和逐文件改造细节待本轮实现定稿后补充；待补项不表示已实现或已发布。</p></div><h2 id="包范围" tabindex="-1">包范围 <a class="header-anchor" href="#包范围" aria-label="Permalink to &quot;包范围&quot;">​</a></h2><table tabindex="0"><thead><tr><th>包名</th><th>职责</th></tr></thead><tbody><tr><td><code>@melt-js/libs-qiankun2-tabs-core</code></td><td>框架无关的页签身份、路由状态与微应用运行时</td></tr><tr><td><code>@melt-js/libs-qiankun2-tabs-vue3</code></td><td>Vue 3 页签管理与宿主 / 子应用适配</td></tr><tr><td><code>@melt-js/libs-qiankun2-tabs-vue2</code></td><td>Vue 2.7 页签管理、页签 UI、缓存与微应用保活适配（<code>Vue.use</code> 注册，不支持 2.6 及以下）</td></tr><tr><td><code>@melt-js/libs-qiankun2-tabs-react</code></td><td>React 子应用、路由与页面缓存适配</td></tr><tr><td><code>@melt-js/tpl-qiankun2-react-vite-app1</code></td><td>React 微应用</td></tr><tr><td><code>@melt-js/tpl-qiankun2-vue2-cli4-main</code></td><td>Vue 2 主应用</td></tr><tr><td><code>@melt-js/tpl-qiankun2-vue2-cli4-app1</code></td><td>Vue 2 微应用一</td></tr><tr><td><code>@melt-js/tpl-qiankun2-vue2-cli4-app2</code></td><td>Vue 2 微应用二</td></tr><tr><td><code>@melt-js/tpl-qiankun2-vue3-cli5-main</code></td><td>Vue 3 主应用</td></tr><tr><td><code>@melt-js/tpl-qiankun2-vue3-cli5-app1</code></td><td>Vue 3 微应用一</td></tr><tr><td><code>@melt-js/tpl-qiankun2-vue3-cli5-app2</code></td><td>Vue 3 微应用二</td></tr></tbody></table><h2 id="在线演示" tabindex="-1">在线演示 <a class="header-anchor" href="#在线演示" aria-label="Permalink to &quot;在线演示&quot;">​</a></h2><p>链接按各包 <code>package.json</code> 的 <code>unpkg</code> 入口生成，站点按当前部署域名改写为对应镜像；页面内容随包发布更新。</p><table tabindex="0"><thead><tr><th>模板 / 示例</th><th>演示地址</th></tr></thead><tbody><tr><td><code>tpl-qiankun2-vue2-cli4-main</code></td><td><a href="https://unpkg.com/@melt-js/tpl-qiankun2-vue2-cli4-main/dist/index.html" target="_blank" rel="noreferrer">演示地址</a></td></tr><tr><td><code>tpl-qiankun2-vue2-cli4-app1</code></td><td><a href="https://unpkg.com/@melt-js/tpl-qiankun2-vue2-cli4-app1/dist/index.html" target="_blank" rel="noreferrer">演示地址</a></td></tr><tr><td><code>tpl-qiankun2-vue2-cli4-app2</code></td><td><a href="https://unpkg.com/@melt-js/tpl-qiankun2-vue2-cli4-app2/dist/index.html" target="_blank" rel="noreferrer">演示地址</a></td></tr><tr><td><code>tpl-qiankun2-vue3-cli5-main</code></td><td><a href="https://unpkg.com/@melt-js/tpl-qiankun2-vue3-cli5-main/dist/index.html" target="_blank" rel="noreferrer">演示地址</a></td></tr><tr><td><code>tpl-qiankun2-vue3-cli5-app1</code></td><td><a href="https://unpkg.com/@melt-js/tpl-qiankun2-vue3-cli5-app1/dist/index.html" target="_blank" rel="noreferrer">演示地址</a></td></tr><tr><td><code>tpl-qiankun2-vue3-cli5-app2</code></td><td><a href="https://unpkg.com/@melt-js/tpl-qiankun2-vue3-cli5-app2/dist/index.html" target="_blank" rel="noreferrer">演示地址</a></td></tr><tr><td><code>tpl-qiankun2-react-vite-app1</code></td><td><a href="https://unpkg.com/@melt-js/tpl-qiankun2-react-vite-app1/dist/index.html" target="_blank" rel="noreferrer">演示地址</a></td></tr></tbody></table><p>子应用单独打开时是独立页面，只有通过主应用进入才能验证页签、保活与路由同步。</p><h2 id="本地联调" tabindex="-1">本地联调 <a class="header-anchor" href="#本地联调" aria-label="Permalink to &quot;本地联调&quot;">​</a></h2><p>在 workspace 根执行 <code>pnpm qk2:dev</code> 启动 Vue 2 CLI 4 组合，或执行 <code>pnpm qk:dev</code> 启动 Vue 3 CLI 5 和 React Vite 组合。命令同时准备 tabs 远程产物和刷新后的代理，并启动模板和 tabs 服务。需要测试模板里的其它远程组件页面时，还需启动端口表中对应的组件服务。</p><h2 id="提供的方法与工具" tabindex="-1">提供的方法与工具 <a class="header-anchor" href="#提供的方法与工具" aria-label="Permalink to &quot;提供的方法与工具&quot;">​</a></h2><table tabindex="0"><thead><tr><th>入口 / 能力</th><th>用途</th></tr></thead><tbody><tr><td>core：<code>MicroAppRuntime</code> / <code>RouteDispatcher</code> / <code>MicroPageCache</code></td><td>运行时、路由调度与页面缓存</td></tr><tr><td>Vue 3：<code>installMicroTabsBridge</code> / <code>createMicroAppCache</code></td><td>主应用桥接与微应用缓存</td></tr><tr><td>Vue 3：<code>useTabQuery</code> / <code>createTabsUrlSync</code></td><td>页签查询状态与 URL 同步</td></tr><tr><td>Vue 2：<code>createTabsManager</code> / <code>tabsManager</code> 插件</td><td>页签管理器创建与 <code>Vue.use</code> 注册（内部完成 registerModules 与 setupPlugins）</td></tr><tr><td>Vue 2：<code>createMicroAppCache</code> / <code>useMicroAppCache</code>（<code>/child</code> 子路径）</td><td>子应用 keep-alive 缓存模型，输出 <code>state.keepAliveList</code> 与 <code>cache.key()</code></td></tr><tr><td>Vue 2：<code>createMicroTabController</code> / <code>installMicroTabsBridge</code> / <code>createTabsUrlSync</code></td><td>子应用页签控制、宿主消息桥接与 URL 同步</td></tr></tbody></table><h2 id="提供的组件" tabindex="-1">提供的组件 <a class="header-anchor" href="#提供的组件" aria-label="Permalink to &quot;提供的组件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>组件 / 分组</th><th>用途</th></tr></thead><tbody><tr><td>Vue 3：<code>MicroAppView</code> 与页签 UI</td><td>微应用容器与标签页，完整清单待补</td></tr><tr><td>Vue 2：<code>DynamicTabsComponent</code> / <code>DynamicContainerComponent</code></td><td>动态页签与容器组件</td></tr></tbody></table><h2 id="接入骨架" tabindex="-1">接入骨架 <a class="header-anchor" href="#接入骨架" aria-label="Permalink to &quot;接入骨架&quot;">​</a></h2><p>模板预加载对应适配包的 <code>hel-meta.json</code>，再导入业务入口。<code>/remote</code> 提供与包根入口一致的具名导出，远程实现使用消费方自己的 Vue 或 React 运行时。子应用入口同步导出 qiankun 四个生命周期，首次执行时等待适配层加载；本地直开同样走这条路径。Vue 2 主应用仍通过 <code>Vue.use</code> 安装页签管理器。</p><h2 id="模板简介" tabindex="-1">模板简介 <a class="header-anchor" href="#模板简介" aria-label="Permalink to &quot;模板简介&quot;">​</a></h2><p>Vue 2 模板来自 qiankun-tabsCache，Vue 3 模板来自 qiankun-vue3-tabsPage。主应用负责导航与应用注册，app1 / app2 用来验证多微应用和多页签。</p><h2 id="从原开源模板快速接入" tabindex="-1">从原开源模板快速接入 <a class="header-anchor" href="#从原开源模板快速接入" aria-label="Permalink to &quot;从原开源模板快速接入&quot;">​</a></h2><p>以下先列改造顺序，具体文件、配置和代码差异在实现定稿后补齐。</p><ol><li>先按框架整理主应用注册项、微应用入口、路由 base 和构建 public path。</li><li>通过包内环境变量配置 HEL 元数据地址，先加载远程适配层，再导入使用 <code>/remote</code> 的业务入口。Vue CLI 4 项目在 <code>vue.config.js</code> 中把 <code>/remote</code> 映射到包声明的导出。</li><li>处理 qiankun bootstrap / mount / unmount / update 生命周期及同一微应用多页签的路由传递。</li><li>仅对需要 hel 组件的微应用增加对应运行时与加载步骤，分别验证切页、回退、刷新和卸载。</li></ol><h2 id="待补内容" tabindex="-1">待补内容 <a class="header-anchor" href="#待补内容" aria-label="Permalink to &quot;待补内容&quot;">​</a></h2><ul><li>[ ] 补 Vue 2 / Vue 3、主应用 / app1 / app2 的职责与差异表。</li><li>[ ] 补页签身份、路由状态、keep-alive 与 URL 同步 API。</li><li>[ ] 补两种上游模板的逐文件改造表、启动组合和部署路径。</li></ul>',24)])])}const k=e(r,[["render",c]]);export{h as __pageData,k as default};
